class MultiKeyGeminiLLM:
    """Rotates across 8 Gemini API keys on 429 ResourceExhausted or quota errors."""
    def invoke(self, messages: Any, **kwargs: Any) -> Any:
        attempts = 0
        max_attempts = len(self.keys)
        last_error = None
        while attempts < max_attempts:
            client = self.get_active_client()
            try:
                return client.invoke(messages, **kwargs)
            except Exception as e:
                err_str = str(e).lower()
                if "429" in err_str or "resourceexhausted" in err_str or "quota" in err_str:
                    print(f"🔄 [MultiKeyGeminiLLM] 429 detected on key {self.current_idx}. Rotating...")
                    self.rotate_to_next_key(error_desc=err_str)
                    attempts += 1
                    continue
                raise e
        # Exhausted all Gemini keys -> Fallback to Bedrock
        print("⚠️ [MultiKeyGeminiLLM] All Gemini keys exhausted. Falling back to Bedrock Converse...")
        return self.bedrock_fallback.invoke(messages, **kwargs)
